class Projection:
    def __init__( self, B ):
        self.B = B

    def reduce_dim( self, X ):
        return  X @ B @ np.linalg.inv(B.T @ B)  

    def reconstruct( self, X_reduced ):
        return X_reduced @ B.T

    def get_projection_matrix( self ):
        P = B @ np.linalg.inv(B.T @ B) @ B.T
        return P

    def project( self , X ):
        P = self.get_projection_matrix()
        return X @ P


