def item_relevancy(col):
    relevant = 1
    r_color = 'background-color: lime'
    nr_color = 'background-color: red'
    res = []
    for v in col:
        if v > relevant:
            res.append(r_color)
        elif (v > 0) & (v <= relevant):
            res.append(nr_color)
        else:
            res.append('')
    return res

